package tw.sunnycoop.widget;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
public class SettingsActivity extends Activity {
 private LinearLayout form;private final Map<String,EditText> fields=new HashMap<>();private final Map<String,Switch> toggles=new HashMap<>();private Spinner sector;private int widgetId;
 private static final String SITE="https://fangyuan-flock-weather.a0321000000.chatgpt.site/index.html";
 public void onCreate(Bundle b){super.onCreate(b);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(Color.BLACK);form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);int pad=(int)(20*getResources().getDisplayMetrics().density);form.setPadding(pad,pad,pad,pad);sc.addView(form);sc.setOnApplyWindowInsetsListener((v,insets)->{form.setPadding(pad,pad+insets.getSystemWindowInsetTop(),pad,pad+insets.getSystemWindowInsetBottom());return insets;});setContentView(sc);
 label("晴舍 4×2 桌面小工具",24);label("溫度・風向・風速・降雨機率\n黑底白字，達警戒變紅；沒有濕度欄位。",14);
 SharedPreferences p=CoopWidget.prefs(this);input("name","場區名稱",p.getString("name","芳苑一場"),false);input("lat","緯度",p.getString("lat","23.924"),true);input("lon","經度",p.getString("lon","120.32"),true);
 rule("high","高溫門檻 °C",32);rule("low","低溫門檻 °C",15);rule("wind","風速門檻 m/s",10);rule("rain","降雨機率門檻 %",70);
 label("迎風提醒（風的來向）",14);sector=new Spinner(this);String[] choices={"關閉","北","東北","東","東南","南","西南","西","西北"};ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices);sector.setAdapter(adapter);sector.setSelection(p.getInt("sector",-1)<0?0:p.getInt("sector",-1)/45+1);form.addView(sector);input("directionSpeed","迎風提醒的最低風速 m/s",Float.toString(p.getFloat("directionSpeed",8)),true);
 button("儲存並更新",()->saveSettings());button("加入桌面小工具",()->{if(!saveSettings())return;AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,CoopWidget.class),null,null);else Toast.makeText(this,"請長按桌面 → 小工具 → 晴舍 4×2 氣象",Toast.LENGTH_LONG).show();});button("開啟晴舍網頁",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(SITE))));
 label("第一次安裝後：長按三星桌面空白處 → 小工具 → 晴舍 4×2 氣象。\n\n小工具使用本機的場區與警戒設定，尚未與網頁雲端設定同步。每小時要求更新，實際時間由 Android 省電與網路狀態決定；可按 ↻ 手動更新。\n\n此小工具顯示戶外估算與預報，不是舍內實測。它不另外發送系統警報；既有背景推播仍請在 Chrome 的晴舍網站啟用。\n\n小工具會把設定座標送至 Open-Meteo 查天氣。資料來源及條款：https://open-meteo.com/ 。門檻範例非養殖建議，預設全部關閉。",12);
 }
 private void label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(size);v.setPadding(0,12,0,8);form.addView(v);}
 private void input(String key,String title,String value,boolean numeric){label(title,13);EditText e=new EditText(this);e.setTextColor(Color.WHITE);e.setSingleLine(true);e.setInputType(numeric?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED:InputType.TYPE_CLASS_TEXT);e.setText(value);e.setContentDescription(title);form.addView(e);fields.put(key,e);}
 private void rule(String key,String title,float def){SharedPreferences p=CoopWidget.prefs(this);input(key,title,Float.toString(p.getFloat(key,def)),true);Switch t=new Switch(this);t.setText("啟用"+title);t.setTextColor(Color.WHITE);t.setChecked(p.getBoolean(key+"On",false));form.addView(t);toggles.put(key,t);}
 private void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());form.addView(b);}
 private boolean saveSettings(){try{String name=fields.get("name").getText().toString().trim();double lat=number("lat"),lon=number("lon");if(name.isEmpty()||name.length()>40||lat< -85||lat>85||lon< -180||lon>180)throw new IllegalArgumentException();float hi=(float)number("high"),lo=(float)number("low"),wi=(float)number("wind"),ra=(float)number("rain"),ds=(float)number("directionSpeed");if(hi< -50||hi>60||lo< -50||lo>60||wi<0||wi>150||ra<0||ra>100||ds<0||ds>150)throw new IllegalArgumentException();SharedPreferences p=CoopWidget.prefs(this);boolean locationChanged=!Double.toString(lat).equals(p.getString("lat","23.924"))||!Double.toString(lon).equals(p.getString("lon","120.32"));SharedPreferences.Editor e=p.edit().putString("name",name).putString("lat",Double.toString(lat)).putString("lon",Double.toString(lon)).putFloat("high",hi).putFloat("low",lo).putFloat("wind",wi).putFloat("rain",ra).putFloat("directionSpeed",ds).putInt("sector",sector.getSelectedItemPosition()==0?-1:(sector.getSelectedItemPosition()-1)*45);for(String key:toggles.keySet())e.putBoolean(key+"On",toggles.get(key).isChecked());if(locationChanged)e.remove("snapshot").remove("fetched");e.apply();CoopWidget.render(this);CoopWidget.schedule(this);if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();}else Toast.makeText(this,"已儲存，正在更新天氣",Toast.LENGTH_SHORT).show();return true;}catch(Exception e){Toast.makeText(this,"請確認名稱、座標與門檻數值範圍",Toast.LENGTH_LONG).show();return false;}}
 private double number(String key){double n=Double.parseDouble(fields.get(key).getText().toString());if(!Double.isFinite(n))throw new IllegalArgumentException();return n;}
}
